/// Two-phase adapter trait OWNED BY SECURITY; implementation stays private to storage.
pub trait CommitStaging {
    type Prepared: PreparedLedgerCommit;
    /// At-most-once: consumes self, stages receipt/association in the already-open txn.
    /// Must not commit or publish by itself.
    fn stage(self, binding: &JournalSealBinding) -> Result<Self::Prepared, Refusal>;
}
pub trait PreparedLedgerCommit {
    /// The one commit method. Performs only the prepared commit and barriers.
    fn commit(self) -> Result<(), Refusal>;
