    /// Single atomic admission transition; wins before the commit syscall.
    pub fn admit_commit(&self) -> bool {
        self.0.compare_exchange(ATT_PREPARING, ATT_COMMIT_ADMITTED, Ordering::SeqCst, Ordering::SeqCst).is_ok()
