    /// The one commit method. Performs only the prepared commit and barriers.
    fn commit(self) -> Result<(), Refusal>;
}

/// Security-owned result. Storage's facade never accepts an externally built one.
pub struct SealOutcome { pub(crate) durable_seal_seq: i64, pub(crate) stopped: StoppedSession }
impl SealOutcome { pub fn durable_seal_seq(&self) -> i64 { self.durable_seal_seq } }

/// Cleanup-only session; still owns the operation lease.
pub struct StoppedSession { session: CommitSession }
impl StoppedSession {
    pub fn operation_ref(&self) -> &str { self.session.operation_ref() }
    pub fn record_rev_cleanup(self) -> Result<(), Refusal> { Ok(()) }
}

/// Atomic attempt state arbitrating observer latch vs commit admission.
pub const ATT_PREPARING: u8 = 0;
pub const ATT_COMMIT_ADMITTED: u8 = 1;
pub const ATT_LATCHED: u8 = 2;

pub struct ObserverLatch(AtomicU8);
impl ObserverLatch {
    pub fn new() -> Self { ObserverLatch(AtomicU8::new(ATT_PREPARING)) }
    /// Fail-stop latch outside the append mutex. Wins only before commit admission.
    pub fn latch(&self) -> bool {
        self.0.compare_exchange(ATT_PREPARING, ATT_LATCHED, Ordering::SeqCst, Ordering::SeqCst).is_ok()
    }
    /// Single atomic admission transition; wins before the commit syscall.
    pub fn admit_commit(&self) -> bool {
        self.0.compare_exchange(ATT_PREPARING, ATT_COMMIT_ADMITTED, Ordering::SeqCst, Ordering::SeqCst).is_ok()
    }
    pub fn state(&self) -> u8 { self.0.load(Ordering::SeqCst) }
}

/// Security owns the whole checkpoint/witness sequence.
/// Consumes JournalWriteTxn, BORROWS the evaluator-minted ReplayedRun.
pub fn seal_under_append_lock<A: CommitStaging>(
    txn: JournalWriteTxn, run: &ReplayedRun, latch: &ObserverLatch, adapter: A,
) -> Result<SealOutcome, (Refusal, StoppedSession)> {
    let JournalWriteTxn { session, journal_seq } = txn;

    // --- durable SEAL + PENDING->COMMITTED witness happen here (elided) ---
    let binding = JournalSealBinding {
        carrier_digest: "c0ffee".into(), grant_generation: 7, journal_seq,
        body_sha256: "b0dy".into(), operation_ref: session.operation_ref().to_string(),
        run_id: run.run_id().to_string(), namespace: session.namespace(),
        execution: session.execution(), store_generation: session.store_generation(),
    };

    // Phase 1: at-most-once staging; may fail without issuing an evidence commit.
    let prepared = match adapter.stage(&binding) {
        Ok(p) => p,
        Err(e) => return Err((e, StoppedSession { session })),
    };

    // Phase 2: recheck freshness, then atomically arbitrate latch vs admission.
    if !latch.admit_commit() {
        // A latch that won while preparing prevents the gate. Adapter is dropped
        // un-committed; the still-open evidence transaction rolls back.
        return Err((Refusal::Latched, StoppedSession { session }));
    }
    match prepared.commit() {
        Ok(()) => Ok(SealOutcome { durable_seal_seq: journal_seq, stopped: StoppedSession { session } }),
        Err(e) => Err((e, StoppedSession { session })),
    }
}
