//! Storage. Depends on contracts, evaluator, platform, security. Security does not depend on storage.
use contracts::Refusal;
use evaluator::ReplayedRun;
use security::{
    begin_journal_txn, seal_under_append_lock, CommitSession, CommitStaging, JournalSealBinding,
    ObserverLatch, PreparedLedgerCommit, SealOutcome,
};

/// Private ledger connection/transaction. Never escapes.
struct LedgerTxn { staged_receipt: Option<(String, u128)>, committed: bool }
impl LedgerTxn {
    fn acquire_non_waiting() -> Result<LedgerTxn, Refusal> {
        Ok(LedgerTxn { staged_receipt: None, committed: false })
    }
}

/// Storage-private adapter implementation; holds the already-open evidence txn.
struct LedgerStaging<'t> { txn: &'t mut LedgerTxn, expected_run: String, next_commit_seq: u128 }

/// Storage-private prepared commit; owns the open txn until the one commit method.
struct PreparedLedger<'t> { txn: &'t mut LedgerTxn }

impl<'t> CommitStaging for LedgerStaging<'t> {
    type Prepared = PreparedLedger<'t>;
    fn stage(self, b: &JournalSealBinding) -> Result<Self::Prepared, Refusal> {
        // Storage validates BOTH owners' exact joins; security never manufactures
        // storage's receipt counter or receipt bytes.
        if b.run_id() != self.expected_run { return Err(Refusal::Ledger); }
        if b.journal_seq() > 9_007_199_254_740_990 { return Err(Refusal::Carrier); }
        // Thirteen-field association + receipt staged in the SAME open transaction.
        self.txn.staged_receipt = Some((b.run_id().to_string(), self.next_commit_seq));
        Ok(PreparedLedger { txn: self.txn })
    }
}
impl<'t> PreparedLedgerCommit for PreparedLedger<'t> {
    fn commit(self) -> Result<(), Refusal> {
        if self.txn.staged_receipt.is_none() { return Err(Refusal::Ledger); }
        self.txn.committed = true; // commit syscall + barriers only
        Ok(())
    }
}

/// Public opaque: returned only by prepare_commit. Owns both prerequisites.
/// NOTE: deliberately does NOT implement Drop, so publish() can move fields out.
pub struct PreparedCommit { run: ReplayedRun, session: CommitSession }

/// Public opaque storage result; constructor private to durable commit validation.
pub struct PublishedCommit { receipt_run_id: String, commit_sequence: u128, seal_seq: i64 }
impl PublishedCommit {
    pub fn receipt_run_id(&self) -> &str { &self.receipt_run_id }
    pub fn commit_sequence(&self) -> u128 { self.commit_sequence }
    pub fn seal_seq(&self) -> i64 { self.seal_seq }
}

pub fn prepare_commit(run: ReplayedRun, session: CommitSession) -> Result<PreparedCommit, Refusal> {
    if session.store_generation() < 0 { return Err(Refusal::Admission); }
    Ok(PreparedCommit { run, session })
}

impl PreparedCommit {
    /// The only publication path. Accepts no external adapter and no external SealOutcome.
    pub fn publish(self, latch: &ObserverLatch) -> Result<PublishedCommit, Refusal> {
        let PreparedCommit { run, session } = self;
        let expected_run = run.run_id().to_string();

        // Fixed order: security grant-journal level-3 first, evidence ledger second,
        // both non-waiting; only then the level-4 append checkpoint inside security.
        let jtxn = begin_journal_txn(session)?;
        let mut ledger = match LedgerTxn::acquire_non_waiting() {
            Ok(l) => l,
            Err(e) => { let _ = e; return Err(Refusal::Ledger); } // consuming abort path
        };
        let outcome: SealOutcome = {
            let adapter = LedgerStaging { txn: &mut ledger, expected_run: expected_run.clone(), next_commit_seq: 42 };
            match seal_under_append_lock(jtxn, &run, latch, adapter) {
                Ok(o) => o,
                Err((e, stopped)) => { let _ = stopped.record_rev_cleanup(); return Err(e); }
            }
        };
        if !ledger.committed { return Err(Refusal::Ledger); }
        let (rid, seq) = ledger.staged_receipt.take().ok_or(Refusal::Ledger)?;
        Ok(PublishedCommit { receipt_run_id: rid, commit_sequence: seq, seal_seq: outcome.durable_seal_seq() })
    }
}
